import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Executive summary","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"property":"og:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/EXECUTIVE-SUMMARY.html"}],["meta",{"name":"twitter:title","content":"Executive summary | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/EXECUTIVE-SUMMARY.md","filePath":"audits/EXECUTIVE-SUMMARY.md","lastUpdated":1794227887000}`),a={name:`audits/EXECUTIVE-SUMMARY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to “Executive summary”">​</a></h1><p><strong>Re-audit date:</strong> 9 November 2026<br><strong>Base:</strong> <code>dev</code> at PR #81 squash merge <code>85f2043c4d06ac4f7bcd65ec5aa18452c98ff38a</code><br><strong>Working branch:</strong> <code>audit/owner-feedback-followups</code><br><strong>Ruleset:</strong> <a href="https://github.com/aaron-fredrick/RULESETS" target="_blank" rel="noreferrer">RULESETS</a> <code>main</code> at <code>79d7dd4f0c0d544ba85abeb19286ef2cae34bf89</code></p><h2 id="overall-assessment" tabindex="-1">Overall assessment <a class="header-anchor" href="#overall-assessment" aria-label="Permalink to “Overall assessment”">​</a></h2><p>The previously identified high-risk security and result-semantics defects have been merged to <code>dev</code>. This follow-up branch adds the owner-approved financial timing rules, central product validation, lightweight AIT metadata, dataset freshness metadata, search-budget calibration, and an initial Playwright browser suite.</p><p><strong>Latest verified CI result: green.</strong> Workflow <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42574353592" target="_blank" rel="noreferrer">42574353592</a> completed successfully. Its Node.js test job passed the test suite, syntax checks, production and dev browser builds, all six Chromium browser smoke tests, documentation-preservation build, and workflow YAML parsing. The run also includes the report fixes for semantic ledger headers, narrow-screen overflow, and print table width. This supersedes the earlier failed print-width run <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42571366220" target="_blank" rel="noreferrer">42571366220</a>.</p><p>The branch is not ready for final release sign-off. Remaining work is broader cross-strategy financial parity, manual and extended report/accessibility QA, real bank-source reviews, and deployed response-header verification. CI success does not establish those manual or external checks.</p><h2 id="finding-disposition" tabindex="-1">Finding disposition <a class="header-anchor" href="#finding-disposition" aria-label="Permalink to “Finding disposition”">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Finding</th><th>Current status</th></tr></thead><tbody><tr><td>SEC-01</td><td>Imported account IDs require HTML attribute encoding</td><td><strong>Completed — PR #75</strong></td></tr><tr><td>FIN-01 / ENG-05</td><td>Pre-withdrawal value must be distinct from closing assets/liabilities</td><td><strong>Completed — PR #75</strong></td></tr><tr><td>FIN-02</td><td>Capital contributed must not be labelled capital invested</td><td><strong>Completed — PR #75</strong></td></tr><tr><td>FIN-03 / DATA-01</td><td>Product-level source provenance in UI, CLI and reports</td><td><strong>Completed — PR #81; manual rendered review remains</strong></td></tr><tr><td>ENG-01</td><td>Installment payout events bounded by simulation window</td><td><strong>Implemented on this branch; regression tests pass</strong></td></tr><tr><td>ENG-02</td><td>Retain and disclose start-year 365/366 denominator convention</td><td><strong>Implemented on this branch; formula unchanged</strong></td></tr><tr><td>ENG-03</td><td>Central FD term validation and maturity horizon</td><td><strong>Implemented on this branch; row-level diagnostics tested</strong></td></tr><tr><td>ENG-04</td><td>Lightweight versioned 10% AIT baseline and IRD source disclosure</td><td><strong>Implemented on this branch; contract tests pass</strong></td></tr><tr><td>SEARCH-01</td><td>Bounded browser search and explicit unlimited mode</td><td><strong>Implemented and calibrated; no optimality proof</strong></td></tr><tr><td>SEARCH-02</td><td>Strategy modules concentrate multiple responsibilities</td><td><strong>Deferred; staged decomposition plan only</strong></td></tr><tr><td>SEARCH-03</td><td>Independent planners require authoritative runtime/parity protection</td><td><strong>Greedy strict-outflow reservation fixed and tested; broader cross-strategy planner parity remains</strong></td></tr><tr><td>DATA-02</td><td>Senior/minor selection is not eligibility verification</td><td><strong>Closed as owner-confirmed scope boundary</strong></td></tr><tr><td>DATA-03</td><td>Special-product caps/eligibility/tax constraints</td><td><strong>Deferred; special products remain research-only</strong></td></tr><tr><td>DATA-04</td><td>Strict CSV structural validation</td><td><strong>Completed — PR #81 merged to dev</strong></td></tr><tr><td>DATA-05</td><td>Simplified transfer-fee model is not a full channel model</td><td><strong>Documented limitation; simplified model retained by owner decision</strong></td></tr><tr><td>DATA-06</td><td>Bank dataset freshness and metadata</td><td><strong>Metadata contract implemented; bank-by-bank source review pending</strong></td></tr><tr><td>DEPLOY-01</td><td>Dev preview assembly under <code>/dev/</code></td><td><strong>Completed on dev — PR #80</strong></td></tr><tr><td>UI-01/02/03</td><td>Reduced-motion scrolling, operable help disclosures, field-associated errors</td><td><strong>Completed — PR #81; manual assistive-technology QA remains</strong></td></tr><tr><td>PRIV-01/02</td><td>Draft retention controls and public privacy/legal disclosures</td><td><strong>Completed on dev — PR #81</strong></td></tr><tr><td>WEB-SEC-02</td><td>Static hosting response-header strategy</td><td><strong>Open verification; GitHub Pages retained by owner decision</strong></td></tr><tr><td>QA-01</td><td>Playwright browser smoke coverage in CI</td><td><strong>Implemented; workflow 42574353592 passed</strong></td></tr><tr><td>QA-REP-01</td><td>Independent standalone report, mobile and print QA</td><td><strong>Automated smoke assertions pass; extended and manual QA remain</strong></td></tr></tbody></table><h2 id="owner-approved-constraints" tabindex="-1">Owner-approved constraints <a class="header-anchor" href="#owner-approved-constraints" aria-label="Permalink to “Owner-approved constraints”">​</a></h2><ul><li><strong>ENG-01:</strong> Preserve the contractual payout sequence; schedule only generated events within the selected simulation window. Do not extend the run or clamp a late installment to maturity. Product maturity must fit within the simulation horizon.</li><li><strong>ENG-02:</strong> Retain the existing start-year 365/366 elapsed-day denominator across the full interval. Do not silently switch to calendar-segmented Actual/Actual.</li><li><strong>ENG-03:</strong> Validate product-term invariants centrally; keep special-product constraints out of the generic model until separately designed.</li><li><strong>ENG-04:</strong> Retain a lightweight 10% Sri Lankan interest AIT baseline with effective date and official source disclosure. Do not build a broad tax-regime engine.</li><li><strong>DATA-03:</strong> Special-product modelling remains deferred.</li><li><strong>DATA-05:</strong> Retain the simplified same-bank/inter-bank fee approximation and label it as an estimate.</li><li><strong>DATA-06:</strong> Track source review, actual economic-data changes and schema migrations independently. Schema-only migrations must preserve review/update dates.</li><li><strong>SEARCH-01:</strong> Retain 10,000 expanded states / 30 seconds as browser baseline; users can deliberately request longer/unlimited searches.</li><li><strong>SEARCH-02:</strong> No broad strategy refactor before parity baselines.</li><li><strong>WEB-SEC-02:</strong> Keep GitHub Pages; no proxy/CDN or hosting migration in this phase.</li></ul><p>Full evidence and source links are in <a href="./OWNER-FEEDBACK-RESEARCH.html">Owner-feedback research</a>.</p><h2 id="remaining-work-ordered" tabindex="-1">Remaining work, ordered <a class="header-anchor" href="#remaining-work-ordered" aria-label="Permalink to “Remaining work, ordered”">​</a></h2><ol><li><strong>SEARCH-03 parity:</strong> Add eligible FD booking, maturity/installment payout, transfer-fee, and future-outflow reserved-liquidity fixtures. Compare booking decisions, event ledgers, obligations, balances, fees, AIT and validity across Greedy, GSS, Absolute R and Absolute R+. Keep the shared runtime authoritative.</li><li><strong>QA-REP-01:</strong> Test offline behaviour, chart initialization and realistic large ledgers. Complete manual print/PDF pagination, keyboard, screen-reader, contrast and 200–400% zoom review on representative browsers/devices.</li><li><strong>DATA-06 source review:</strong> Recheck all 29 bank entries against official sources where possible. Populate <code>dataset_reviewed_at</code> only after an actual source review and <code>dataset_updated_at</code> only when an economic product input materially changed. Leave unknown dates blank.</li><li><strong>WEB-SEC-02:</strong> Inspect actual production and <code>/dev/</code> response headers; document which headers GitHub Pages cannot configure.</li><li><strong>Release hygiene:</strong> Keep the follow-up branch isolated from <code>dev</code> until the remaining acceptance gates are addressed or explicitly accepted as residual risks. Existing PR #82 remains a draft.</li></ol><p>Keep SEARCH-02 refactoring, DATA-03 activation, richer DATA-05 channel modelling, main-branch preview integration and external legal counsel review deferred unless separately authorised.</p><h2 id="verification-boundary" tabindex="-1">Verification boundary <a class="header-anchor" href="#verification-boundary" aria-label="Permalink to “Verification boundary”">​</a></h2><p>Workflow success is evidence for the automated checks in that run only. It does not establish screen-reader output, full WCAG conformance, real-device behaviour, actual printed/PDF pagination, live bank rates, legal compliance or deployed HTTP response headers.</p><p>The audit is a risk-based source review, not formal verification, financial-product certification, penetration testing, a legal opinion or a full WCAG audit. External bank rates, product eligibility, tax relief, fee schedules and contractual payout terms still require direct verification with the relevant institution or qualified professional.</p><h2 id="latest-follow-up-checkpoint-—-9-november-2026" tabindex="-1">Latest follow-up checkpoint — 9 November 2026 <a class="header-anchor" href="#latest-follow-up-checkpoint-—-9-november-2026" aria-label="Permalink to “Latest follow-up checkpoint — 9 November 2026”">​</a></h2><p>The Greedy strategy now checks ranked, simulation-period-eligible FD options against future strict obligations. It reserves cumulative strict outflows due before candidate maturity, books only the residual amount when that residual meets the FD minimum, and otherwise skips the candidate unless it matures on or before the due date. Consolidation candidates are checked after transfer fees and account-level balance movements. The shared simulation runtime remains authoritative for settlement.</p><p>Three focused regressions cover cash reservation, fallback to a shorter candidate that matures on the due date, and cumulative obligations before maturity. The legacy Greedy migration-parity fixture was narrowed to deferred outflows so it continues to test unchanged legacy behaviour without asserting parity across the newly introduced strict-reservation rule.</p><p>Workflow <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42598559354" target="_blank" rel="noreferrer">42598559354</a> passed all 268 Node tests, syntax checks, production/dev builds, six Chromium browser tests, documentation-preservation build and workflow YAML parsing.</p><p>SEARCH-03 remains <strong>partial</strong>, but the specific Greedy future-strict-outflow defect is addressed. Broader cross-strategy planner parity across multi-account, transfer, inflow and multiple-obligation combinations remains open. This is not a full financial-parity or release sign-off.</p><h2 id="_9-november-2026-—-ship-gate-recheck" tabindex="-1">9 November 2026 — ship-gate recheck <a class="header-anchor" href="#_9-november-2026-—-ship-gate-recheck" aria-label="Permalink to “9 November 2026 — ship-gate recheck”">​</a></h2><ul><li>Current verified implementation head: <code>aa8684e0999a9554af3f6c0185a4eeb0d9e5a233</code>.</li><li>Full CI: <a href="https://github.com/aaron-fredrick/FD-Calculator/actions/runs/42598559354" target="_blank" rel="noreferrer">42598559354</a> — successful; 268 tests passed, with syntax, production/dev build, six Chromium browser smoke tests, documentation-preservation build and workflow YAML parsing all green.</li><li>The Greedy strict-outflow reservation gap is fixed within candidate selection; the shared runtime still owns authoritative outflow settlement.</li><li><strong>Keep PR #82 in draft.</strong> Broader cross-strategy planner parity, extended report/accessibility QA, bank-source review and deployed response-header verification remain. Do not begin those later phases as part of this bounded fix.</li></ul>`,24)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};